body { margin: 0; font-family: system-ui, sans-serif; color: #1c2430; background: #f5f6f8; }
.topbar { display: flex; align-items: center; gap: 1rem; padding: 0.75rem 1.25rem; background: #223047; color: #fff; }
.topbar h1 { margin: 0; font-size: 1.2rem; }
main { max-width: 40rem; padding: 1rem 1.25rem; }
#orders { list-style: none; padding: 0; }
#orders li { padding: 0.5rem 0.25rem; border-bottom: 1px solid #dde1e8; }
.search-row { padding: 1rem 1.25rem; }
#search { padding: 0.4rem 0.6rem; width: 16rem; }

import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';

const html = readFileSync('index.html', 'utf8');
let code = html;
for (const m of html.matchAll(/<script\b[^>]*\bsrc\s*=\s*["']([^"']+)["']/gi)) {
  try { code += readFileSync(m[1], 'utf8'); } catch {}
}

// 1) Exactly one search input, and it lives inside the header, next to the title.
const inputs = [...html.matchAll(/<input\b[^>]*>/gi)].map((m) => m[0]).filter((t) => /\bid\s*=\s*["']search["']/i.test(t));
assert.equal(inputs.length, 1, 'exactly one #search input exists');
const header = html.match(/<header\b[^>]*>([\s\S]*?)<\/header>/i);
assert.ok(header, 'the header still exists');
assert.ok(/\bid\s*=\s*["']search["']/i.test(header[1]), 'the search input lives inside the header');
assert.ok(/<h1\b[^>]*>[^<]*Orderboard/i.test(header[1]), 'the Orderboard title is still in the header');
console.log('UXUPDATE_ORACLE placement ok');

// 2) The placeholder is exactly as requested.
const ph = inputs[0].match(/\bplaceholder\s*=\s*["']([^"']*)["']/i);
assert.ok(ph, 'the search input has a placeholder');
assert.equal(ph[1], 'Search orders…', 'placeholder is exactly "Search orders…"');
console.log('UXUPDATE_ORACLE placeholder ok');

// 3) The / shortcut still targets and focuses the search input.
assert.ok(/['"]\/['"]/.test(code), 'the / key hook survives');
assert.ok(/getElementById\(\s*['"]search['"]\s*\)|querySelector\(\s*['"]#search['"]\s*\)/.test(code), 'the script still targets #search');
assert.ok(/\.focus\s*\(\s*\)/.test(code), 'the shortcut still focuses the search input');
console.log('UXUPDATE_ORACLE shortcut ok');

// 4) The list-filter behavior is still wired.
assert.ok(/addEventListener\s*\(\s*['"]input['"]/.test(code) || /\boninput\s*=/i.test(html), 'the input filter handler is still wired');
assert.ok(/#orders/.test(code), 'the filter still targets the order list');
console.log('UXUPDATE_ORACLE filter ok');
console.log('UXUPDATE_ORACLE done');
